func TestUserService_ListUsers(t *testing.T) {
	mockRepo := new(MockUserRepository)
	service := NewUserService(mockRepo, nil)

	ctx := context.Background()
	clinicID := uuid.New()
	filter := pagination.Filter{Page: 1, Limit: 10}

	users := []*model.User{
		{ID: uuid.New(), Name: "Test User 1", Role: "admin"},
		{ID: uuid.New(), Name: "Test User 2", Role: "receptionist"},
	}

	mockRepo.On("GetByClinicID", ctx, clinicID, filter).Return(users, int64(2), nil)

	res, err := service.ListUsers(ctx, clinicID, filter)

	assert.NoError(t, err)
	assert.NotNil(t, res)
	assert.Equal(t, int64(2), res.Meta.Total)
	assert.Equal(t, 2, len(res.Data))
	assert.Equal(t, "Test User 1", res.Data[0].Name)

	mockRepo.AssertExpectations(t)
}
